int kvm_pit_set_state(struct kvm *kvm, struct kvm_pit_state2 *ps)
{
    int i;

    mutex_lock(&kvm->pit_state->mutex);
    kvm->pit_state->flags &= ~KVM_PIT_FLAGS_HPET_LEGACY;
    kvm->pit_state->flags |= ps->flags & KVM_PIT_FLAGS_HPET_LEGACY;
    for (i = 0; i < 3; i++) {
        kvm->pit_state->channels[i].count = ps->channels[i].count;
        kvm->pit_state->channels[i].init_count = ps->channels[i].init_count;
        kvm->pit_state->channels[i].latched_count = ps->channels[i].latched_count;
        kvm->pit_state->channels[i].latched_flags = ps->channels[i].latched_flags;
        kvm->pit_state->channels[i].status = ps->channels[i].status;
        kvm->pit_state->channels[i].init = ps->channels[i].init;
        kvm->pit_state->channels[i].count_load = ps->channels[i].count_load;
        kvm->pit_state->channels[i].retrieving = ps->channels[i].retrieving;
        kvm->pit_state->channels[i].output = ps->channels[i].output;
        kvm->pit_state->channels[i].is_periodic = ps->channels[i].is_periodic;
    }
    mutex_unlock(&kvm->pit_state->mutex);

    return 0;
}

int kvm_update_pit_state(struct kvm *kvm, struct kvm_pit_state2 *ps) {
    int i;

    mutex_lock(&kvm->pit_state->mutex);
    kvm->pit_state->hpet = ps->hpet;
    for (i = 0; i < 3; i++) {
        kvm->pit_state->channels[i].state = ps->channels[i].state;
        kvm->pit_state->channels[i].count = ps->channels[i].count;
        kvm->pit_state->channels[i].init_count = ps->channels[i].init_count;
        kvm->pit_state->channels[i].mode = ps->channels[i].mode;
        kvm->pit_state->channels[i].latched_count = ps->channels[i].latched_count;
        kvm->pit_state->channels[i].latched_flag = ps->channels[i].latched_flag;
        kvm->pit_state->channels[i].retrigger = ps->channels[i].retrigger;
        kvm->pit_state->channels[i].nextpit = ps->channels[i].nextpit;
        kvm->pit_state->channels[i].count_load_time = ps->channels[i].count_load_time;
    }
    mutex_unlock(&kvm->pit_state->mutex);

    return 0;
}

